using System;
using System.IO;
using System.IO.Compression;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using System.Web.Script.Serialization;
using System.Linq;
using Velopack;
using Velopack.Locators;
namespace PZ3D {
 static class VelopackNativeTests {
  static int passed; static RSACryptoServiceProvider rsa; static byte[] package=Package();
  static byte[] Package(){using(var memory=new MemoryStream()){using(var zip=new ZipArchive(memory,ZipArchiveMode.Create,true)){using(var writer=new StreamWriter(zip.CreateEntry("OrangeZomboidLauncher.nuspec").Open()))writer.Write("<package><metadata><id>OrangeZomboidLauncher</id><version>9.0.0</version><authors>fixture</authors><description>fixture</description></metadata></package>");using(var writer=new StreamWriter(zip.CreateEntry("lib/net45/Squirrel.exe").Open()))writer.Write("upstream-process-boundary-fixture");}return memory.ToArray();}}
  static byte[] Raw(string version="9.0.0",string name=null){return Encoding.UTF8.GetBytes(new JavaScriptSerializer().Serialize(new{schema=1,appId="OrangeZomboidLauncher",channel="win",version=version,fileName=name??("OrangeZomboidLauncher-"+version+"-full.nupkg"),length=package.Length,sha256=CoreReleaseProtocol.Hash(package),notes="fixture"}));}
  static byte[] Sign(byte[] raw){return rsa.SignData(raw,CryptoConfig.MapNameToOID("SHA256"));}
  static void Assert(bool v,string message){if(!v)throw new Exception(message);}
  static void Reject(Action a){try{a();}catch(Exception){return;}throw new Exception("Accepted invalid input");}
  static void Test(string n,Action a){try{a();passed++;Console.WriteLine("PASS "+n);}catch(Exception e){Console.WriteLine("FAIL "+n+": "+e.GetType().FullName+" "+e.Message);throw;}}
  static void Main(string[] args){if(args.Length==3&&args[0]=="--bootstrap"){DistributionBootstrap.Read(args[1],File.ReadAllText(args[2]));Console.WriteLine("PASS native bootstrap inventory");return;}rsa=new RSACryptoServiceProvider(2048);rsa.PersistKeyInCsp=false;string key=rsa.ToXmlString(false),root=Path.Combine(Path.GetTempPath(),"ozl-vpk-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{
   Test("valid signature binds full package",()=>{var f=VelopackFeed.Verify(Raw(),Sign(Raw()),key,"1.0.0");Assert(f.Version=="9.0.0"&&f.Length==package.Length,"metadata");});
   Test("unsigned, tampered, replay, foreign and mixed metadata rejected",()=>{Reject(()=>VelopackFeed.Verify(Raw(),new byte[256],key,"1.0.0"));Reject(()=>VelopackFeed.Verify(Raw("9.0.1"),Sign(Raw()),key,"1.0.0"));Reject(()=>VelopackFeed.Verify(Raw("1.0.0"),Sign(Raw("1.0.0")),key,"2.0.0"));byte[] foreign=Raw("9.0.0","https://evil.test/full.nupkg");Reject(()=>VelopackFeed.Verify(foreign,Sign(foreign),key,"1.0.0"));});
   Test("portable and installed state outside replaceable current",()=>{string current=Path.Combine(root,"current"),local=Path.Combine(root,"local");Assert(DistributionPaths.Resolve(root,current,true,local)==Path.Combine(root,"OrangeLauncherRuntime"),"portable");Assert(DistributionPaths.Resolve(root,current,false,local)==Path.Combine(local,"PZ3DManager","Velopack"),"installed");Reject(()=>DistributionPaths.Resolve(current,current,true,local));});
   Test("real SDK discovery and package download use authenticated source",()=>{int requests=0;var source=new AuthenticatedVelopackSource(key,"1.0.0",(url,t)=>{requests++;return new MemoryStream(url.EndsWith(".sig")?Sign(Raw()):url.EndsWith(".json")?Raw():package);});var locator=new TestVelopackLocator("OrangeZomboidLauncher","1.0.0",root);var manager=new UpdateManager(source,null,locator);var update=manager.CheckForUpdatesAsync().GetAwaiter().GetResult();Assert(update.TargetFullRelease.FileName.EndsWith("-full.nupkg"),"full package");manager.DownloadUpdatesAsync(update,null,CancellationToken.None).GetAwaiter().GetResult();source.VerifyPackage(Path.Combine(root,update.TargetFullRelease.FileName),update.TargetFullRelease);Assert(requests==3,"signed envelope and package fetched");});
   Test("invalid signature does not trigger GitHub fallback",()=>{int requests=0;var source=new AuthenticatedVelopackSource(key,"1.0.0",(url,t)=>{requests++;return new MemoryStream(url.EndsWith(".sig")?new byte[256]:Raw());});Reject(()=>new UpdateManager(source,null,new TestVelopackLocator("OrangeZomboidLauncher","1.0.0",root)).CheckForUpdatesAsync().GetAwaiter().GetResult());Assert(requests==2,"no downgrade fallback");});
   Test("transport failure alone uses canonical GitHub",()=>{var urls=new List<string>();var source=new AuthenticatedVelopackSource(key,"1.0.0",(url,t)=>{urls.Add(url);if(url.StartsWith("https://orangezl.com/"))throw new System.Net.WebException("offline");return new MemoryStream(url.EndsWith(".sig")?Sign(Raw()):Raw());});source.GetReleaseFeed(null,"OrangeZomboidLauncher","win",null,null).GetAwaiter().GetResult();Assert(urls.Count==3&&urls[1].StartsWith("https://github.com/LiuDaCheng666/orange-zomboid-launcher/"),"fixed fallback");});
   Test("cancelled ready update cannot hand off",()=>{var source=new AuthenticatedVelopackSource(key,"1.0.0",(url,t)=>new MemoryStream(url.EndsWith(".sig")?Sign(Raw()):url.EndsWith(".json")?Raw():package));var backend=new VelopackUpdateBackend(source,new TestVelopackLocator("OrangeZomboidLauncher","1.0.0",root));backend.Check();Wait(backend);backend.Download();Wait(backend);Assert(backend.Status().state=="Ready",backend.Status().message);backend.Cancel();Reject(()=>backend.Apply());Assert(backend.Status().state=="Cancelled","cancel state");backend.Dispose();});
   Test("changed downloaded bytes rejected before apply",()=>{var source=new AuthenticatedVelopackSource(key,"1.0.0",(url,t)=>new MemoryStream(url.EndsWith(".sig")?Sign(Raw()):url.EndsWith(".json")?Raw():package));var feed=source.GetReleaseFeed(null,"OrangeZomboidLauncher","win",null,null).Result;string p=Path.Combine(root,"bad");File.WriteAllText(p,"tampered");Reject(()=>source.VerifyPackage(p,feed.Assets[0]));});
   Test("signed replay and mixed release signature never fall back",()=>{foreach(string v in new[]{"0.9.0","9.0.1"}){int requests=0;var source=new AuthenticatedVelopackSource(key,"1.0.0",(url,t)=>{requests++;return new MemoryStream(url.EndsWith(".sig")?Sign(Raw(v=="0.9.0"?v:"9.0.0")):Raw(v));});Reject(()=>source.GetReleaseFeed(null,"OrangeZomboidLauncher","win",null,null).GetAwaiter().GetResult());Assert(requests==2,"replay/mix fallback");}});
   Test("foreign host and noncanonical repo cannot enter transport",()=>{foreach(string url in new[]{"https://evil.test/x","https://github.com/evil/repo/releases/download/v9.0.0/file","http://orangezl.com/releases/v9.0.0/file","https://orangezl.com:8443/releases/v9.0.0/file","https://orangezl.com/releases/v9.0.0/file?redirect=1"})Assert(!VelopackNetwork.InitialAllowed(new Uri(url)),"foreign URL accepted");});
   Test("bad downloaded bytes are removed and never retried as transport failure",()=>{int requests=0;var source=new AuthenticatedVelopackSource(key,"1.0.0",(url,t)=>{requests++;return new MemoryStream(url.EndsWith(".sig")?Sign(Raw()):url.EndsWith(".json")?Raw():new byte[package.Length]);});var feed=source.GetReleaseFeed(null,"OrangeZomboidLauncher","win",null,null).Result;string p=Path.Combine(root,"bad-download");Reject(()=>source.DownloadReleaseEntry(null,feed.Assets[0],p,null,CancellationToken.None).GetAwaiter().GetResult());Assert(requests==3&&!File.Exists(p),"integrity failure fallback or stale file");});
   Test("cancellation during real SDK discovery cannot publish available",()=>{var entered=new ManualResetEventSlim();var source=new AuthenticatedVelopackSource(key,"1.0.0",(url,t)=>{entered.Set();t.WaitHandle.WaitOne();t.ThrowIfCancellationRequested();return null;});using(var b=new VelopackUpdateBackend(source,new TestVelopackLocator("OrangeZomboidLauncher","1.0.0",root))){b.Check();Assert(entered.Wait(5000),"lookup did not begin");b.Cancel();Thread.Sleep(100);Assert(b.Status().state=="Cancelled","stale available");Reject(()=>b.Download());Reject(()=>b.Apply());}});
   Test("signed bootstrap rejects missing SDK inventory and changed Web assets",()=>{string dir=Path.Combine(root,"bootstrap");Directory.CreateDirectory(dir);var files=new List<CoreFile>();foreach(string name in DistributionBootstrap.Owned){string p=Path.Combine(dir,name);Directory.CreateDirectory(Path.GetDirectoryName(p));File.WriteAllBytes(p,package);files.Add(new CoreFile{path=name,url="",length=package.Length,sha256=CoreReleaseProtocol.Hash(package)});}Action write=()=>{var bytes=Encoding.UTF8.GetBytes(new JavaScriptSerializer().Serialize(new{schema=1,version=AppVersion.Current,files=files}));File.WriteAllBytes(Path.Combine(dir,"velopack-bootstrap.json"),bytes);File.WriteAllBytes(Path.Combine(dir,"velopack-bootstrap.sig"),Sign(bytes));};write();DistributionBootstrap.Read(dir,key);File.WriteAllText(Path.Combine(dir,"Web","app.js"),"tampered");Reject(()=>DistributionBootstrap.Read(dir,key));File.WriteAllBytes(Path.Combine(dir,"Web","app.js"),package);files.RemoveAll(f=>f.path=="Velopack.dll");write();Reject(()=>DistributionBootstrap.Read(dir,key));});
   Test("persisted authenticated high-water mark rejects previously superseded release",()=>{string checkpoint=Path.Combine(root,"accepted.bin");Func<string,CancellationToken,Stream> latest=(url,t)=>new MemoryStream(url.EndsWith(".sig")?Sign(Raw("9.0.1")):Raw("9.0.1"));new AuthenticatedVelopackSource(key,"1.0.0",latest,checkpoint).GetReleaseFeed(null,"OrangeZomboidLauncher","win",null,null).GetAwaiter().GetResult();var older=new AuthenticatedVelopackSource(key,"1.0.0",(url,t)=>new MemoryStream(url.EndsWith(".sig")?Sign(Raw()):Raw()),checkpoint);Reject(()=>older.GetReleaseFeed(null,"OrangeZomboidLauncher","win",null,null).GetAwaiter().GetResult());File.WriteAllText(checkpoint,"tampered");Reject(()=>new AuthenticatedVelopackSource(key,"1.0.0",latest,checkpoint));});
   Test("real SDK emits silent wait-exit apply with restart only after verified ready",()=>{string dir=Path.Combine(root,"handoff");Directory.CreateDirectory(dir);var locator=new RecordingLocator(dir);var source=new AuthenticatedVelopackSource(key,"1.0.0",(url,t)=>new MemoryStream(url.EndsWith(".sig")?Sign(Raw()):url.EndsWith(".json")?Raw():package));using(var b=new VelopackUpdateBackend(source,locator)){Reject(()=>b.Apply());Assert(locator.Starts==0,"early apply");b.Check();Wait(b);b.Download();Wait(b);Assert(b.Status().state=="Ready",b.Status().message);b.Apply();Assert(b.Status().state=="Restarting"&&locator.Starts==1,"SDK handoff missing");Assert(locator.Arguments.Contains("apply")&&!locator.Arguments.Contains("--norestart")&&locator.Arguments.Contains("--waitPid")&&locator.Arguments.Contains("--silent"),string.Join(" ",locator.Arguments));}});
   Test("tampered upstream updater image cannot execute",()=>{string dir=Path.Combine(root,"tamper-helper");Directory.CreateDirectory(dir);var locator=new RecordingLocator(dir);var source=new AuthenticatedVelopackSource(key,"1.0.0",(url,t)=>new MemoryStream(url.EndsWith(".sig")?Sign(Raw()):url.EndsWith(".json")?Raw():package));using(var b=new VelopackUpdateBackend(source,locator)){b.Check();Wait(b);b.Download();Wait(b);Assert(b.Status().state=="Ready",b.Status().message);File.WriteAllText(locator.UpdateExePath,"foreign executable");Reject(()=>b.Apply());Assert(locator.Starts==0,"tampered updater executed");}});
   Test("monitor copies are outside current and authenticate both source and cache",()=>{string dir=Path.Combine(root,"worker","current"),stable=Path.Combine(root,"worker","OrangeLauncherRuntime");Directory.CreateDirectory(dir);var files=new List<CoreFile>();foreach(string name in DistributionBootstrap.Owned){string p=Path.Combine(dir,name);Directory.CreateDirectory(Path.GetDirectoryName(p));File.WriteAllBytes(p,package);files.Add(new CoreFile{path=name,url="",length=package.Length,sha256=CoreReleaseProtocol.Hash(package)});}var bytes=Encoding.UTF8.GetBytes(new JavaScriptSerializer().Serialize(new{schema=1,version=AppVersion.Current,files=files}));File.WriteAllBytes(Path.Combine(dir,"velopack-bootstrap.json"),bytes);File.WriteAllBytes(Path.Combine(dir,"velopack-bootstrap.sig"),Sign(bytes));string source=Path.Combine(dir,"橙子启动器.exe"),image=ManagedBackgroundWorker.PrepareDistribution(source,key,stable);Assert(image.StartsWith(stable+Path.DirectorySeparatorChar)&&!image.StartsWith(dir+Path.DirectorySeparatorChar),"worker inside current");File.WriteAllText(image,"corrupt cache");Reject(()=>ManagedBackgroundWorker.PrepareDistribution(source,key,stable));File.Delete(image);File.WriteAllText(source,"corrupt source");Reject(()=>ManagedBackgroundWorker.PrepareDistribution(source,key,stable));});
   Test("cancellation during package transfer cannot become ready or apply",()=>{string dir=Path.Combine(root,"cancel-transfer");Directory.CreateDirectory(dir);var entered=new ManualResetEventSlim();var source=new AuthenticatedVelopackSource(key,"1.0.0",(url,t)=>url.EndsWith(".nupkg")?(Stream)new BlockedTransfer(entered,t):new MemoryStream(url.EndsWith(".sig")?Sign(Raw()):Raw()));var locator=new RecordingLocator(dir);using(var b=new VelopackUpdateBackend(source,locator)){b.Check();Wait(b);b.Download();Assert(entered.Wait(5000),"transfer did not start");b.Cancel();Thread.Sleep(100);Assert(b.Status().state=="Cancelled","cancelled transfer became ready");Reject(()=>b.Apply());Assert(locator.Starts==0&&!Directory.GetFiles(dir,"*.partial").Any(),"cancel retained apply/partial");}});
   Console.WriteLine(passed+" native Velopack tests passed");
  }finally{rsa.Dispose();Directory.Delete(root,true);}}
  static void Wait(VelopackUpdateBackend b){var deadline=DateTime.UtcNow.AddSeconds(10);while(b.Status().state=="Checking"||b.Status().state=="Downloading"){if(DateTime.UtcNow>deadline)throw new Exception("timeout");Thread.Sleep(20);}}
  sealed class BlockedTransfer:MemoryStream {readonly ManualResetEventSlim entered;readonly CancellationToken token;internal BlockedTransfer(ManualResetEventSlim e,CancellationToken t):base(package){entered=e;token=t;}public override int Read(byte[] b,int o,int n){entered.Set();token.WaitHandle.WaitOne();token.ThrowIfCancellationRequested();return base.Read(b,o,n);}}
  sealed class RecordingLocator:IVelopackLocator,IProcessImpl {
   readonly TestVelopackLocator inner; internal int Starts;internal string[] Arguments;
   internal RecordingLocator(string root){File.WriteAllText(Path.Combine(root,"Update.exe"),"non-executable fixture");inner=new TestVelopackLocator("OrangeZomboidLauncher","1.0.0",root,Path.Combine(root,"current"),root,Path.Combine(root,"Update.exe"),"win",null,null,Path.Combine(root,"current","launcher.exe"));}
   public string AppId{get{return inner.AppId;}}public string RootAppDir{get{return inner.RootAppDir;}}public string PackagesDir{get{return inner.PackagesDir;}}public string AppContentDir{get{return inner.AppContentDir;}}public string AppTempDir{get{return inner.AppTempDir;}}public string UpdateExePath{get{return inner.UpdateExePath;}}public SemanticVersion CurrentlyInstalledVersion{get{return inner.CurrentlyInstalledVersion;}}public string ThisExeRelativePath{get{return inner.ThisExeRelativePath;}}public string Channel{get{return "win";}}public string AppUserModelId{get{return inner.AppUserModelId;}}public Velopack.Logging.IVelopackLogger Log{get{return inner.Log;}}public bool IsPortable{get{return true;}}public IProcessImpl Process{get{return this;}}
   public void AddLogger(Velopack.Logging.IVelopackLogger logger){inner.AddLogger(logger);}public List<VelopackAsset> GetLocalPackages(){return inner.GetLocalPackages();}public VelopackAsset GetLatestLocalFullPackage(){return inner.GetLatestLocalFullPackage();}public Guid? GetOrCreateStagedUserId(){return inner.GetOrCreateStagedUserId();}
   public string GetCurrentProcessPath(){return Path.Combine(AppContentDir,"launcher.exe");}public uint GetCurrentProcessId(){return 12345;}public void StartProcess(string file,IEnumerable<string> args,string workingDirectory,bool x){Assert(file==UpdateExePath,"foreign process handoff");Starts++;Arguments=args.ToArray();}public void Exit(int code){throw new Exception("Framework must not exit before host guards close");}
  }
 }
}
